+    const original = 'module.exports = {};\n';
+    const once = prependMetroFallbackComment(original);
+    const twice = prependMetroFallbackComment(once);
+
+    expect(once).toContain(METRO_FALLBACK_COMMENT_MARKER);
+    expect(twice).toBe(once);
+  });
+});
